<!--vbase-->
<template>
  <div class="row bg-grey-2 q-pb-md">
    <div class="col-12 q-pl-sm q-mt-md">
      <div class="row full-width justify-center">
        <iframe
          :src="path"
          title="Main menu"
          width="90%"
          height="900px"
        ></iframe>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { DOC2API_URL } from 'src/pages/APIs';
import { defineComponent, ref } from 'vue';
import { useImageAuth } from 'src/composables/useImageAuth';
import helperMixin from 'src/mixins/helperMixin.js';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
    components: {},
  watch: {
    processing(active: boolean) {
      active ? this.showLoading() : this.hideLoading();
    },
  },
  mounted() {
    this.init();
  },

  unmounted: function () {
    // unmounted
  },
  data() {
    return {
      docId: '',
      filename: '',
    };
  },
  methods: {
    init() {
      try {
        this.processing = true;
        this.docId = this.$route.params.id as string;
        this.filename = this.$route.params.filename as string;
        this.path =
          DOC2API_URL +
          '/resource/document/' +
          this.docId +
          '/' +
          this.docId +
          '.pdf?download=false' +
          '&' +
          this.tokenQueryParam;
        if (!this.path) {
          logInfo('pdf not found');
        }
      } catch (err: any) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
  setup() {
    const { tokenQueryParam } = useImageAuth();
    return {path: ref(''),
      processing: ref(false),
      tokenQueryParam};
  },
});
</script>
